export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Create sprite with placeholder material; will assign texture after load
  const material = new ctx.THREE.SpriteMaterial({
    transparent: true,
    depthWrite: false, // typical for sprites
  });
  const sprite = new ctx.THREE.Sprite(material);
  group.add(sprite);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Atlas region: left=0, top=0, width=512, height=320 (from config)
      const srcX = 0;
      const srcY = 0;
      const srcW = 512;
      const srcH = 320;

      const texW = tex.image.width;
      const texH = tex.image.height;

      // UV repeat to isolate the region
      tex.repeat.set(srcW / texW, srcH / texH);
      // UV offset (Three.js uses bottom-left origin for UVs)
      tex.offset.set(srcX / texW, (texH - srcY - srcH) / texH);

      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Scale sprite to match aspect ratio of atlas region (512/320 ≈ 1.6)
  // The group's scale is left at (1,1,1) – adapter will position as specified.
  sprite.scale.set(1.6, 1, 1);

  // Cleanup resources
  group.userData.cleanup = () => {
    material.dispose();
    if (material.map) material.map.dispose();
    // Sprite has no geometry to dispose, but clean up any child if needed
    if (sprite.geometry) sprite.geometry.dispose();
  };

  // No interactions or text content – node is static.
  group.userData.handlers = {};

  return group;
}
